from base_replanteo import *
done={}
for p in OUT.glob('*/resultado.json'):
 try:
  r=read(p);done[p.parent.name]={k:r[k] for k in ['validation','od_validation','graph_validation','OOF','in_sample','best_epoch','epochs_run','seconds'] if k in r}
 except (ValueError,KeyError):pass
state=read(OUT/'sesiones_activas.json');active=state.get('active',state.get('tool_sessions',[]));pending=state.get('pending',[])
