for item in extra_state.get('active',[]):
 if not (OUT/item['experiment']/'resultado.json').exists() and item['pid'] not in [q.get('pid') for q in active]:active.append(item)
write(OUT/'plan_activo.json',dict(goal='MAE confirmation <73.5 seconds; unchanged primary OD cohort',status='active',completed=done,running=active,next=pending,Test='sealed; no Test labels used in adaptive search',candidate_preservation_threshold_s=131.06,current_best=dict(id=BEST.name,mae_s=131.25671207822356),storage='Original data and TransferTraj preserved. No disk CDF banks. Discarded weights removed only after result/hash checks.'))
lines=['# Replanteamiento operativo activo','','Objetivo: MAE de confirmación <73,5 s con la misma cohorte y consulta OD. Test sigue cerrado. Mejor resultado conservado: 131,2567 s en Validación completa.','','## Resultados de esta etapa','']
for name,r in done.items():lines.append('- '+name+': '+json.dumps(r,ensure_ascii=False))
lines+=['','## Conclusiones y siguientes pruebas','','La memoria de duraciones sin base no mejora el modelo conservado. La variante de residuos fuera de bloque terminó en 136,3058 s, frente a 136,1861 s de su base; tampoco mejora en MAE. No se vuelve a ampliar esta variante sin una hipótesis adicional. Se prueba memoria de residuos calculados fuera de cada bloque; consultas y candidatos de entrenamiento pertenecen al mismo bloque excluido para impedir que la base transmita la etiqueta de consulta.','El proceso espacial sin dirección obtuvo 138,22 s en toda Validación. Su cabeza OD obtuvo 138,34 s y la rama espacial aislada con respaldo en consultas sin soporte, 154,22 s. Estas son comparaciones entre cabezas del mismo modelo, no una ablación con entrenamiento separado. La integración actual apenas aporta respecto a su propia cabeza directa y queda por encima de la referencia TabM.','En Train con semanas reservadas, añadir dirección entrante reduce NLL de siguiente zona de 0,77217 a 0,64690 y sube acierto de 72,75 % a 76,37 %. Esto justifica ampliar el estado, pero NO demuestra beneficio en MAE de duración. La nueva inferencia conserva dirección hipotética de cada transición; la dirección real de la consulta nunca se entrega. Se ejecuta también una corrección neuronal sobre un prior de conteos locales, excluyendo de esos conteos todo el bloque de la consulta Train; este prior no excluye el ajuste neuronal ni el grafo permitido entrenado con Train.','La descomposición liga tiempos de movimiento y bajo desplazamiento mediante convolución; el control sin esa supervisión terminó en 131,4176 s y el supervisado en 131,6273 s. El incremento de error supervisado es 0,2097 s, IC95 % exploratorio por día [0,0442; 0,3703]. Bajo desplazamiento es una aproximación GPS, no una etiqueta humana de parada.','Un selector con acceso a la verdad que eligiera entre las cinco salidas anteriores tendría 100,44 s. Es un diagnóstico privilegiado e inutilizable como predictor; limita solo la selección entre esas cinco salidas, no nuevas funciones ni otras arquitecturas.','','## Ejecución activa','',json.dumps(dict(active=active,pending=pending),ensure_ascii=False,indent=2),'','El objetivo permanece activo. La parada temprana de un ajuste individual no cierra la investigación. No se declara éxito ni una imposibilidad general. Se conserva la referencia principal hasta validar una alternativa mejor.']
(OUT/'README.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(json.dumps(dict(completed=list(done),active=active,pending=pending)))

